messages.content:
Tool response:
Tool: remove_product_from_wishlist
Description: Remove Product From Wishlist
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "The ID of the user whose wishlist contains the product",
          "title": "User Id"
        },
        "wishlist_id": {
          "type": "integer",
          "description": "The ID of the wishlist from which to remove the product",
          "title": "Wishlist Id"
        },
        "product_id": {
          "type": "integer",
          "description": "The ID of the product to remove from the wishlist",
          "title": "Product Id"
        }
      },
      "required": [
        "user_id",
        "wishlist_id",
        "product_id"
      ]
    }
